{
  "findings": [
    {
      "check_id": "CKV_GCP_2",
      "title": "Ensure Google compute firewall ingress does not allow unrestricted ssh access",
      "resource": "google_compute_firewall.allow_http_https",
      "severity": "MEDIUM",
      "explanation": "The firewall rule allows unrestricted access (0.0.0.0/0) to ports 80, 443, and 8080. While HTTP/HTTPS access is expected for web servers, unrestricted access to port 8080 can pose a security risk if not explicitly required."
    }
  ],
  "patched_code": "resource \"google_compute_firewall\" \"allow_http_https\" {\n  name    = \"digital-asset-trading-platform-firewall-web\"\n  network = google_compute_network.digital_asset_trading_vpc.name\n  allow {\n    protocol = \"tcp\"\n    ports    = [\"80\", \"443\"]\n  }\n  source_ranges = [\"0.0.0.0/0\"]\n  target_tags   = [\"web-server\"]\n}\n",
  "fix_summary": "Removed port 8080 from the allowed ports in the firewall rule to prevent unnecessary exposure."
}
